def minTimeMaxPower(n, edges, power, cost, source, target):
    INF = float('inf')

    # Adjacency list: out[u] = list of (v, travel time)
    out = [[] for _ in range(n)]
    for u, v, t in edges:
        out[u].append((v, t))

    # dist[node][p] = minimum time to be at node with exactly p power left
    dist = [[INF] * (power + 1) for _ in range(n)]
    dist[source][power] = 0

    # Power strictly decreases on every move, so process power from high to low
    for p in range(power, -1, -1):
        for u in range(n):
            d = dist[u][p]
            # Skip unreachable states and nodes that cannot afford to forward the signal
            if d == INF or p < cost[u]:
                continue
            new_p = p - cost[u]
            for v, t in out[u]:
                if d + t < dist[v][new_p]:
                    dist[v][new_p] = d + t

    # Pick the minimum time at the target; scanning high power first keeps the larger power on ties
    best_time = INF
    best_power = -1
    for p in range(power, -1, -1):
        if dist[target][p] < best_time:
            best_time = dist[target][p]
            best_power = p

    if best_time == INF:
        return [-1, -1]
    return [best_time, best_power]
